from synframe_session import *
from datetime import datetime,timezone
io=host();op=json.loads((ROOT/'work/synframe-operation.json').read_text(encoding='utf-8'))
contents=json.loads((ROOT/'work/sf-package-contents.json').read_text(encoding='utf-8'))
receipts=[io.write_package(contents,path=ROOT/'outputs/업무정리_SynFrame_개발계획.html',format='html',source='현재 조합 비교·원문대조에서 작성한 개발방법 권고'),io.write_package(contents,path=ROOT/'outputs/업무정리_SynFrame_개발계획.json',format='json',source='동일한 열 항목의 개발방법 권고 원문')]
assert json.loads(Path(receipts[1]['path']).read_text(encoding='utf-8'))==contents
html=Path(receipts[0]['path']).read_text(encoding='utf-8')
assert '<meta charset="utf-8">' in html and all(k in html for k in contents)
at=datetime.now(timezone.utc).isoformat()
comparison={'assessed_at':at,'event':'이번 조합·기여·조건 비교와 개발단계/검증범위 평가','contents':contents,'observed_artifacts':receipts,'scope':'문서상 기능과 현재 목적의 의미비교. 실제 제품실행/성능실측 아님.','decision':'WPF/로컬정본·SQLite/restic 제어 경로를 우선권고하고 WinUI/Tauri/Avalonia/Kopia를 실제대안으로 보존. MS UI테스트는 후속조건부 추가.','simplification':'WPF 경로에 WinUI개발스킬·Sandbox·커스텀스킬·추가이미지생성을 무조건 추가하지 않는다. 기존자료를 usermanual로 옮기게 하지 않고 호스트가 구현·검증한다.'}
support={'assessed_at':at,'target':'원문 F1~F4에 대한 현재 해석의 지지','scope':'계획과 조언요청의 관계','source_locator':'계획 전체25절, 사용자 질문 원문, cap-alignment/selection/roadmap/delivery@1','findings':{'F1':'계획검토와 다음진행방법은 개발설계·위험시험·전체단계로 대응. 구현미착수와 전체승인대기는 명시.','F2':'스킬이름에 그치지 않고 실제역할·입출력·수행주체·조건·추가기여를 비교.','F3':'필수계약 전문을 로딩하고 실제관리연산·관측·폐쇄/전파·검토·채택·반환을 이번실행에서 수행해야 한다. 당시 미완료절차를 지금 완료로 미리 주장하지 않는다.','F4':'Windows 로컬프로그램과 폴더정본·클릭미리보기/외부문서열기·로컬백업을 보존. 웹게시/외부분석으로 대체하지 않는다.'},'conclusion':'현재해석을 지지한다. 최종검토/채택/완료는 이후 실제기록 확인까지 남음.'}
omission={'assessed_at':at,'target':'현재기준과 별개로 원문목적·사용조건에서 누락·과잉 대조','scope':'기록통일·업무수용판단·탐색기접근·과거제출물재사용·원본복구','source_locator':'원문 및 계획 GOAL/R02/L08~15/W11~17/PVT05/B08~09/F11~15/DF02~06','source_to_result':'화면뿐 아니라 고유ID·원래주기/최초시각·동시편집보존·실제복원·보수예상·전체범위가 계획/통과조건에 보존됐다.','result_to_source':'WPF/SQLite/restic/개발메타파일/실패저널은 요구된기능을 위한 기술제안으로 표시했다. 사용자가 이를 이미 확정했거나 명세승인했다고 쓰지 않았다.','counterfactual_scope':['화면이 완성되어도 과거파일을 수정하거나 탐색기이동으로 동일업무를 잃으면 목적실패 → 고유ID·과거원본복사·재대조/충돌검증.','백업파일이 있어도 유형/설정/암호를 복원하지 못하면 목적실패 → 전체범위·복구정보·별도빈위치 복원시험.','진행률없는 숫자를 정확한잔여량처럼 보여주면 새업무수용판단에 오해 → 보수예상·기한미정량·오늘포함/완료제외로 명시.','구현단계를 나눈다는 이유로 반복/연간일정/검색을 빠뜨리면 전체목표실패 → 최종범위 대응표와 전체인수조건 유지.'],'observed_structures':'Kopia의 내장자동GUI를 단순수동대안으로 제외하지 않았고, WinUI이름의 UI테스트도 WPF적용을 확인해 비교와 조건부작업에 반영했다.','remaining_uncertainty_assessment':'실제레이어/표시줄/속도/키보관구현은 제품시제품·인수영역이며 이 조언은 선행관문과 실패시재검토를 제공한다. 숨은선호/구현성공을 확정하지 않는다. 현재 권고의 중요원문 누락은 관측하지 못했다.','conclusion':'원문 양방향/목적실패 조건을 현재범위에서 처리. 기술제안은 승인대기제품명세와 구분. 새요구나 실제반박이 있으면 재평가.'}
for n,value in [('sf-comparison.json',comparison),('sf-support.json',support),('sf-omission.json',omission)]:save(n,value)
files=[(ROOT/'work'/n,'현재호스트의 실제 비교/대조 평가: '+n) for n in ['sf-comparison.json','sf-support.json','sf-omission.json']]+[(r['path'],r['source']) for r in receipts]
op=io.preserve_files(op,files);save('synframe-operation.json',op)
c=io.work_context(op);save('synframe-context.json',c)
print(json.dumps({'assessed_at':at,'artifacts':receipts,'revision':c['revision'],'state_digest':c['state_digest'],'operation':c['operation'],'selected_tasks':[{'requested_ref':t['requested_ref'],'current_ref':HostIO.reference(t['current'])} for t in c['selected_tasks']],'consumers':[{'declared_ref':x['declared_ref'],'current_ref':HostIO.reference(x['current'])} for x in c['consumers']],'pending_propagation_count':c['pending_propagation_count'],'propagation_obligations':c['propagation_obligations']},ensure_ascii=False))
